# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KUR\'AN TİLAVETİ VE MUSHAF KAVRAMLARI (مَفَاهِيمُ التِّلَاوَةِ وَالْمُصْحَفِ)</text>\n  <rect x="20" y="44" width="210" height="176" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">التَّجْوِيدُ وَالتَّرْتِيلُ</text>\n  <text x="125" y="88" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">(Tecvit ve Tertîl)</text>\n  <rect x="32" y="100" width="186" height="106" rx="6" fill="#ffffff" stroke="#93c5fd"/>\n  <text x="125" y="122" text-anchor="middle" font-size="9.5" fill="#334155">• Harflerin mahreç ve sıfatlarına</text>\n  <text x="125" y="140" text-anchor="middle" font-size="9.5" fill="#334155">uygun olarak tane tane okumak.</text>\n  <text x="125" y="164" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">أَقْرَأُ الْقُرْآنَ بِالتَّجْوِيدِ</text>\n  <text x="125" y="184" text-anchor="middle" font-size="9" fill="#475569">(Kur\'an\'ı tecvitle okurum.)</text>\n  <rect x="245" y="44" width="210" height="176" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">خَتْمُ الْقُرْآنِ وَالْجُزْءُ</text>\n  <text x="350" y="88" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">(Hatim ve Cüz Düzeni)</text>\n  <rect x="257" y="100" width="186" height="106" rx="6" fill="#ffffff" stroke="#86efac"/>\n  <text x="350" y="122" text-anchor="middle" font-size="9.5" fill="#334155">• 30 cüz (ثَلَاثُونَ جُزْءًا) ve 114</text>\n  <text x="350" y="140" text-anchor="middle" font-size="9.5" fill="#334155">surenin baştan sona okunması.</text>\n  <text x="350" y="164" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">خَتَمَ الطَّالِبُ الْقُرْآنَ الْكَرِيمَ</text>\n  <text x="350" y="184" text-anchor="middle" font-size="9" fill="#475569">(Öğrenci Kur\'an\'ı hatmetti.)</text>\n  <rect x="470" y="44" width="210" height="176" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">الْمُقَابَلَةُ فِي رَمَضَانَ</text>\n  <text x="575" y="88" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">(Mukabele Geleneği)</text>\n  <rect x="482" y="100" width="186" height="106" rx="6" fill="#ffffff" stroke="#fcd34d"/>\n  <text x="575" y="122" text-anchor="middle" font-size="9.5" fill="#334155">• Karşılıklı okuma ve Mushaf\'tan</text>\n  <text x="575" y="140" text-anchor="middle" font-size="9.5" fill="#334155">takip etme sünneti.</text>\n  <text x="575" y="164" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">نَسْتَمِعُ إِلَى الْمُقَابَلَةِ فِي الْمَسْجِدِ</text>\n  <text x="575" y="184" text-anchor="middle" font-size="9" fill="#475569">(Mescitte mukabele dinleriz.)</text>\n</svg>', '<svg viewBox="0 0 700 225" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="225" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KUR\'AN METİNLERİNDEKİ TEMEL DİNÎ KAVRAMLAR AĞI</text>\n  <rect x="25" y="46" width="150" height="156" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="100" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">الْحُرُوفُ الْمُقَطَّعَةُ</text>\n  <text x="100" y="92" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#7e22ce">(Hurûf-u Mukattaa)</text>\n  <text x="100" y="114" text-anchor="middle" font-size="9" fill="#334155">29 surenin başında</text>\n  <text x="100" y="130" text-anchor="middle" font-size="9" fill="#334155">yer alan kesik harfler:</text>\n  <text x="100" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">الم · يس · طه · حم</text>\n  <rect x="190" y="46" width="150" height="156" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="265" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">الْوَحْيُ وَالْهِدَايَةُ</text>\n  <text x="265" y="92" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1d4ed8">(Vahiy ve Hidayet)</text>\n  <text x="265" y="114" text-anchor="middle" font-size="9" fill="#334155">Allah\'ın peygamberlerine</text>\n  <text x="265" y="130" text-anchor="middle" font-size="9" fill="#334155">indirdiği ilahi mesaj ve</text>\n  <text x="265" y="146" text-anchor="middle" font-size="9" fill="#334155">doğru yola rehberlik.</text>\n  <rect x="355" y="46" width="150" height="156" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="430" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">الدَّعْوَةُ وَالْعُبُودِيَّةُ</text>\n  <text x="430" y="92" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#15803d">(Davet ve Kulluk)</text>\n  <text x="430" y="114" text-anchor="middle" font-size="9" fill="#334155">İnsanları tevhide çağırma</text>\n  <text x="430" y="130" text-anchor="middle" font-size="9" fill="#334155">ve Yaratıcıya samimi</text>\n  <text x="430" y="146" text-anchor="middle" font-size="9" fill="#334155">kulluk (ubûdiyyet).</text>\n  <rect x="520" y="46" width="155" height="156" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="597" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">خَلِيلُ اللّٰهِ وَالْقَصَصُ</text>\n  <text x="597" y="92" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#b45309">(Halîlullâh ve Kıssalar)</text>\n  <text x="597" y="114" text-anchor="middle" font-size="9" fill="#334155">Hz. İbrahim\'in unvanı;</text>\n  <text x="597" y="130" text-anchor="middle" font-size="9" fill="#334155">putları (الأصنام) reddeden</text>\n  <text x="597" y="146" text-anchor="middle" font-size="9" fill="#334155">ibretlik peygamber kıssası.</text>\n</svg>', '<svg viewBox="0 0 700 225" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="225" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HZ. LOKMAN\'IN OĞLUNA ÖĞÜTLERİ (سُورَةُ لُقْمَانَ: 12-19)</text>\n  <rect x="20" y="46" width="210" height="158" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">1. İNANÇ VE AİLE (Ayet 12-15)</text>\n  <text x="125" y="90" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">اشْكُرْ لِلّٰهِ · لَا تُشْرِكْ بِاللّٰهِ</text>\n  <text x="125" y="110" text-anchor="middle" font-size="9" fill="#334155">• Allah\'a şükretmek</text>\n  <text x="125" y="128" text-anchor="middle" font-size="9" fill="#334155">• Şirkten uzak durmak (لَظُلْمٌ عَظِيمٌ)</text>\n  <text x="125" y="146" text-anchor="middle" font-size="9" fill="#334155">• Anne-babaya iyilik ve teşekkür</text>\n  <text x="125" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#b91c1c">(وَوَصَّيْنَا الْإِنْسَانَ بِوَالِدَيْهِ)</text>\n  <rect x="245" y="46" width="210" height="158" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">2. İBADET VE SABIR (Ayet 17)</text>\n  <text x="350" y="90" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">أَقِمِ الصَّلَاةَ · وَاصْبِرْ</text>\n  <text x="350" y="110" text-anchor="middle" font-size="9" fill="#334155">• Namazı dosdoğru kılmak</text>\n  <text x="350" y="128" text-anchor="middle" font-size="9" fill="#334155">• İyiliği emretmek (وَأْمُرْ بِالْمَعْرُوفِ)</text>\n  <text x="350" y="146" text-anchor="middle" font-size="9" fill="#334155">• Kötülükten sakındırmak (وَانْهَ عَنِ الْمُنْكَرِ)</text>\n  <text x="350" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#1d4ed8">• Musibetlere sabretmek</text>\n  <rect x="470" y="46" width="210" height="158" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">3. TEVAZU VE ADAP (Ayet 18-19)</text>\n  <text x="575" y="90" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">وَاقْصِدْ فِي مَشْيِكَ · وَاغْضُضْ مِنْ صَوْتِكَ</text>\n  <text x="575" y="110" text-anchor="middle" font-size="9" fill="#334155">• İnsanlara kibirle yüz çevirmemek</text>\n  <text x="575" y="128" text-anchor="middle" font-size="9" fill="#334155">• Yeryüzünde böbürlenerek yürümemek</text>\n  <text x="575" y="146" text-anchor="middle" font-size="9" fill="#334155">• Yürüyüşte ölçülü olmak</text>\n  <text x="575" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#15803d">• Konuşurken sesini alçaltmak</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
